    {
        cJSON_Delete(null);
        return NULL;
    }
    memcpy(name_copy, name, name_length);
    null->string = name_copy;

    if (object->child == NULL)
    {
        object->child = null;
        null->prev = null;
        null->next = NULL;
    }
    else
    {
        tail = object->child->prev;
        if (tail == NULL)
        {
            tail = object->child;
            while (tail->next != NULL)
            {
                tail = tail->next;
            }
            object->child->prev = tail;
        }
        tail->next = null;
        null->prev = tail;
        null->next = NULL;
        object->child->prev = null;
    }

    return null;
}
